import io.github.markusaugust.streamlord.html.*
import kotlin.time.Duration.Companion.seconds

fun DIV.ticks() {
    dataOnInterval("@get('/tick')") { leading = true }
    dataOnIntersect("@get('/more')") { threshold = 150 }
    dataOnIntersect("@get('/more')") {
        half = true
        full = true
    }
    dataOn("click", "@post('/x')") { debounceLeading = true }
    dataOnInterval("@get('/tick')") { duration = 0.seconds }
    dataOnInterval("@get('/tick')") { duration = 2.seconds; leading = true }
    dataOnIntersect("@get('/more')") { threshold = 50; once = true }
    dataOn("click", "@post('/x')") { throttle = 1.seconds; throttleTrailing = true }
}

import io.github.markusaugust.streamlord.html.*

fun DIV.quiet() {
    dataOnClick("@post('/x')") { // debounceLeading = true
        once = true
        /* throttleTrailing = true */
    }
}
